arguments.content:
import pytest
from typing import Annotated
from fastapi import FastAPI, Depends, Response, Query
from fastapi.testclient import TestClient
from pytest import raises

def modify_response():
    return Response(content="modified")

def test_response_dependency():
    app = FastAPI()

    @app.get("/")
    def endpoint(response: Annotated[Response, Depends(modify_response)]):
        return response

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    assert response.text == "modified"

def test_response_no_dependency():
    app = FastAPI()

    @app.get("/")
    def endpoint(response: Response):
        return response

    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200

def test_response_dependency_with_query_fails():
    app = FastAPI()

    def endpoint(response: Annotated[Response, Depends(modify_response), Query()]):
        return response

    with raises(AssertionError, match="Cannot specify FastAPI annotation for type"):
        app.get("/")(endpoint)

